sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // Do nothing while the form first loads, or if the user clears the Apply Template field
    if (isLoading || newValue === '') {
        return;
    }

    // Call our server-side TimeTrackerUtils Script Include via GlideAjax
    var ga = new GlideAjax('x_783736_time_tr_0.TimeTrackerUtils');
    ga.addParam('sysparm_name', 'getTemplateDetails');
    ga.addParam('sysparm_template_id', newValue); // Sends the selected template's Sys ID

    // Wait for the server's JSON reply and populate Project, Hours, and Comment
    ga.getXMLAnswer(function(response) {
        if (!response) {
            return;
        }

        // Convert the JSON text string back into a JavaScript object
        var data = JSON.parse(response);

        if (data.found) {
            g_form.setValue('project', data.project);
            g_form.setValue('hours', data.hours);
            g_form.setValue('comment', data.comment);
            g_form.addInfoMessage('Template applied.');
        }
    });
}
